CREATE DATABASE IF NOT EXISTS auk_uc27 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE auk_uc27;
CREATE TABLE employees (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, can_contract TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY, customer_code VARCHAR(24) UNIQUE NOT NULL, full_name VARCHAR(120) NOT NULL, phone VARCHAR(20) NOT NULL, cccd VARCHAR(20) NOT NULL, license_number VARCHAR(40) NOT NULL, license_expiry DATE NOT NULL, profile_valid TINYINT(1) NOT NULL DEFAULT 1, rental_allowed TINYINT(1) NOT NULL DEFAULT 1, unpaid_fee DECIMAL(12,2) NOT NULL DEFAULT 0, customer_type ENUM('THANH_VIEN','VANG_LAI') NOT NULL DEFAULT 'THANH_VIEN');
CREATE TABLE car_models (id INT AUTO_INCREMENT PRIMARY KEY, model_code VARCHAR(24) UNIQUE NOT NULL, model_name VARCHAR(120) NOT NULL, daily_rate DECIMAL(12,2) NOT NULL);
CREATE TABLE cars (id INT AUTO_INCREMENT PRIMARY KEY, car_code VARCHAR(24) UNIQUE NOT NULL, model_id INT NOT NULL, license_plate VARCHAR(20) UNIQUE NOT NULL, status ENUM('SAN_SANG','DA_THUE') NOT NULL DEFAULT 'SAN_SANG', FOREIGN KEY (model_id) REFERENCES car_models(id));
CREATE TABLE rental_requests (id INT AUTO_INCREMENT PRIMARY KEY, request_code VARCHAR(24) UNIQUE NOT NULL, customer_id INT NOT NULL, model_id INT NOT NULL, status ENUM('CHO_XU_LY','DA_LAP_HOP_DONG') NOT NULL DEFAULT 'CHO_XU_LY', FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(model_id) REFERENCES car_models(id));
CREATE TABLE contracts (id INT AUTO_INCREMENT PRIMARY KEY, contract_code VARCHAR(30) UNIQUE NOT NULL, request_id INT NOT NULL UNIQUE, customer_id INT NOT NULL, car_id INT NOT NULL, employee_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, rental_days INT NOT NULL, daily_rate DECIMAL(12,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES rental_requests(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(car_id) REFERENCES cars(id), FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE rentals (id INT AUTO_INCREMENT PRIMARY KEY, contract_id INT NOT NULL UNIQUE, customer_id INT NOT NULL, car_id INT NOT NULL, status ENUM('DANG_THUE','HOAN_TAT') NOT NULL DEFAULT 'DANG_THUE', FOREIGN KEY(contract_id) REFERENCES contracts(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(car_id) REFERENCES cars(id));
