CREATE TABLE IF NOT EXISTS fee_payments (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, employee_id INT NOT NULL, amount DECIMAL(12,2) NOT NULL, note VARCHAR(255), paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(employee_id) REFERENCES employees(id));

